# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_spans

LONG_DAY = [Span(9 * 60 + 4, 17 * 60 + 11), Span(60, 150)]
EXPECTED = ["09:00-17:15 (8h 15m)", "01:00-02:30 (1h 30m)"]


def rejects(spans, step):
    with unittest.TestCase().assertRaises(ValueError):
        round_spans(spans, step)


class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        self.assertEqual(round_spans(LONG_DAY, 15), EXPECTED)

    def test_bad_steps_raise(self):
        rejects(LONG_DAY, 0), rejects(LONG_DAY, -5), rejects(LONG_DAY, 7)

    def test_collapsed_span_raises(self):
        rejects([Span(61, 64)], 15)
